insert into public.activity_overviews (slug, overview, updated_at) values
  ($s$gifted/sieve_eratosthenes$s$, $ov$수 격자에서 소수를 단계별·자동으로 골라내며 에라토스테네스의 체 원리를 체험하고, 어떤 수까지의 실제 소수 개수와 근삿값을 표·그래프로 비교하며 소수정리를 탐구하는 활동.$ov$, now()),
