-- 20260623_activity_overviews_seed_gifted.sql
-- 활동 개요 시드 — 영재 23개 미니활동.
-- activity_overviews(slug PK) 에 upsert. 재실행 멱등. 관리자가 /admin/overviews 에서 수정 가능.
-- galton_board·pascal 2종은 확통과 같은 컴포넌트라 동일 개요를 gifted 슬러그로 함께 넣는다.
--
-- 적용:  Supabase SQL 에디터에서 실행.
-- 검증:  select count(*) from activity_overviews where slug like 'gifted/%' or slug = 'etc/chaosgame';

on conflict (slug) do update set
  overview = excluded.overview,
  updated_at = now();
